<?php
namespace Azuriom\Plugin\GamingHubCore\Services;
use Azuriom\Plugin\GamingHubCore\Contracts\CapabilityReader; use Azuriom\Plugin\GamingHubCore\Contracts\CapabilityReaderRegistry; use Azuriom\Plugin\GamingHubCore\Contracts\CapabilityResolver; use Azuriom\Plugin\GamingHubCore\Contracts\PublicDataPolicyResolver; use Azuriom\Plugin\GamingHubCore\Contracts\SharedDataGateway; use Azuriom\Plugin\GamingHubCore\Data\SharedDataResult; use Azuriom\Plugin\GamingHubCore\Models\Server; use Throwable;
final class DefaultSharedDataGateway implements SharedDataGateway { public function __construct(private CapabilityResolver $resolver,private CapabilityReaderRegistry $readers,private PublicDataPolicyResolver $policies,private SharedDataCache $cache,private \Illuminate\Contracts\Container\Container $container){} public function supports(Server $s,string $c):bool{$p=$this->resolver->resolve($s,$c);return $p!==null&&$this->readers->has($p->providerType,$c);} public function read(Server $s,string $c):SharedDataResult{$p=$this->resolver->resolve($s,$c);if($p===null)return SharedDataResult::unsupported($c,(int)$s->getKey());$class=$this->readers->readerClass($p->providerType,$c);if($class===null)return SharedDataResult::unavailable($c,(int)$s->getKey(),'missing_reader');try{$reader=$this->container->make($class);if(!$reader instanceof CapabilityReader)return SharedDataResult::failed($c,(int)$s->getKey(),'configuration_invalid','Registered reader contract is invalid.');$key=$this->cache->key((int)$s->getKey(),$p,$c);$r=$this->cache->remember($key,$reader->cacheTtl(),fn()=>$reader->read($s,$p));if(!$r instanceof SharedDataResult)return SharedDataResult::failed($c,(int)$s->getKey(),'invalid_response','Reader returned an invalid result.');foreach(array_keys($r->data) as $dataKey)if(!NormalizedDataKeys::valid((string)$dataKey))return SharedDataResult::failed($c,(int)$s->getKey(),'invalid_response','Reader returned an unregistered generic key.');return $r;}catch(\Illuminate\Validation\ValidationException $e){return SharedDataResult::failed($c,(int)$s->getKey(),'configuration_invalid','Provider configuration is invalid.');}catch(Throwable $e){\Illuminate\Support\Facades\Log::warning('Gaming Hub provider read failed.', ['server_id'=>(int)$s->getKey(),'capability'=>$c,'error_code'=>$this->errorCode($e)]);return SharedDataResult::failed($c,(int)$s->getKey(),$this->errorCode($e),'Provider read failed.');}} public function readMany(Server $s,array $caps):array{$out=[];foreach(array_values(array_unique($caps)) as $c)$out[$c]=$this->read($s,$c);return $out;} public function publicRead(Server $s,string $c):SharedDataResult{$r=$this->read($s,$c);$filtered=$this->policies->filter($s,$r->data,$r->sourceLabel);return new SharedDataResult($r->capability,$r->serverId,$r->status,$filtered['data'],$r->observedAt,$r->sourceUpdatedAt,null,null,$r->errorCode,null,$filtered['source']);} private function errorCode(Throwable $e):string{$m=strtolower($e->getMessage());return str_contains($m,'timeout')?'timeout':(str_contains($m,'auth')?'authentication_failed':(str_contains($m,'connect')?'connection_failed':'unknown_error'));} }
